BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."StaffMemberMonitoringPolicy" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "MinimumCaptureIntervalSeconds" integer NOT NULL,
    "MaximumCaptureIntervalSeconds" integer NOT NULL,
    "HeartbeatIntervalSeconds" integer NOT NULL,
    "DelayedAfterSeconds" integer NOT NULL,
    "UnreachableAfterSeconds" integer NOT NULL,
    "OfflineRetentionDays" integer NOT NULL,
    "MaximumOfflineBytes" bigint NOT NULL,
    "ImageQuality" integer NOT NULL,
    "CaptureAllMonitors" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    "IsSoftDeleted" boolean NOT NULL,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamp without time zone NULL,
    CONSTRAINT "FK_StaffMemberMonitoringPolicy_Institution" FOREIGN KEY ("InstitutionId")
        REFERENCES skolenza."Institution" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffMemberMonitoringPolicy_Institution"
    ON skolenza."StaffMemberMonitoringPolicy" ("InstitutionId")
    WHERE "IsActive" = true AND "IsSoftDeleted" = false;

CREATE TABLE IF NOT EXISTS skolenza."StaffMemberMonitoringAgent" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AgentInstanceId" uuid NOT NULL,
    "InstitutionId" bigint NOT NULL,
    "StaffMemberId" bigint NOT NULL,
    "PolicyId" bigint NOT NULL,
    "DeviceName" character varying(200) NOT NULL,
    "CredentialHash" character varying(64) NOT NULL,
    "AgentVersion" character varying(50) NULL,
    "LastHeartbeatDateTime" timestamp without time zone NULL,
    "LastCaptureDateTime" timestamp without time zone NULL,
    "LastSuccessfulUploadDateTime" timestamp without time zone NULL,
    "PendingCaptureCount" integer NOT NULL,
    "LastErrorCode" character varying(100) NULL,
    "IsActive" boolean NOT NULL,
    "IsSoftDeleted" boolean NOT NULL,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamp without time zone NULL,
    CONSTRAINT "FK_StaffMemberMonitoringAgent_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StaffMemberMonitoringAgent_StaffMember" FOREIGN KEY ("StaffMemberId") REFERENCES skolenza."StaffMember" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StaffMemberMonitoringAgent_Policy" FOREIGN KEY ("PolicyId") REFERENCES skolenza."StaffMemberMonitoringPolicy" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffMemberMonitoringAgent_Instance" ON skolenza."StaffMemberMonitoringAgent" ("AgentInstanceId");
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffMemberMonitoringAgent_CredentialHash" ON skolenza."StaffMemberMonitoringAgent" ("CredentialHash");
CREATE INDEX IF NOT EXISTS "IX_StaffMemberMonitoringAgent_Institution_StaffMember" ON skolenza."StaffMemberMonitoringAgent" ("InstitutionId", "StaffMemberId");
CREATE INDEX IF NOT EXISTS "IX_StaffMemberMonitoringAgent_LastHeartbeat" ON skolenza."StaffMemberMonitoringAgent" ("LastHeartbeatDateTime");

CREATE TABLE IF NOT EXISTS skolenza."StaffMemberScreenCapture" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CaptureId" uuid NOT NULL,
    "InstitutionId" bigint NOT NULL,
    "StaffMemberId" bigint NOT NULL,
    "MonitoringAgentId" bigint NOT NULL,
    "CapturedAtUtc" timestamp without time zone NOT NULL,
    "ReceivedAtUtc" timestamp without time zone NOT NULL,
    "MonitorNumber" integer NOT NULL,
    "ContentType" character varying(50) NOT NULL,
    "ContentLength" bigint NOT NULL,
    "ChecksumSha256" character varying(64) NOT NULL,
    "StorageObjectKey" character varying(1000) NOT NULL,
    CONSTRAINT "FK_StaffMemberScreenCapture_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StaffMemberScreenCapture_StaffMember" FOREIGN KEY ("StaffMemberId") REFERENCES skolenza."StaffMember" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StaffMemberScreenCapture_Agent" FOREIGN KEY ("MonitoringAgentId") REFERENCES skolenza."StaffMemberMonitoringAgent" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StaffMemberScreenCapture_Agent_Capture" ON skolenza."StaffMemberScreenCapture" ("MonitoringAgentId", "CaptureId");
CREATE INDEX IF NOT EXISTS "IX_StaffMemberScreenCapture_Institution_StaffMember_Captured" ON skolenza."StaffMemberScreenCapture" ("InstitutionId", "StaffMemberId", "CapturedAtUtc");

COMMIT;
